using System;using System.Linq;using Mono.Cecil;using Mono.Cecil.Cil;
class PatchHome {
 static string Ops(MethodDefinition m){if(!m.HasBody)return "NO_BODY";var ins=m.Body.Instructions;return String.Join("\n",ins.Select(i=>i.OpCode.Name+":"+(i.Operand is Instruction?"@"+ins.IndexOf((Instruction)i.Operand):i.Operand is Instruction[]?String.Join(",",((Instruction[])i.Operand).Select(x=>ins.IndexOf(x).ToString())):i.Operand==null?"":i.Operand.ToString())));}
 static int Main(string[] args){var a=AssemblyDefinition.ReadAssembly(args[0]);var module=a.MainModule;var type=module.Types.First(t=>t.FullName=="Tizen.Tv.App.FirstScreen.CsfsShowController");var method=type.Methods.First(m=>m.Name=="SetWindowVisible"&&m.Parameters.Count==2);if(method.ReturnType.FullName!="System.Void"||method.Parameters.Any(x=>x.ParameterType.FullName!="System.Boolean"))throw new Exception("Unexpected signature");
 var before=module.GetTypes().SelectMany(t=>t.Methods).ToDictionary(m=>m.FullName,m=>Ops(m));var file=module.GetTypeReferences().First(t=>t.FullName=="System.IO.File");var exception=module.GetTypeReferences().First(t=>t.FullName=="System.Exception");var write=new MethodReference("WriteAllText",module.TypeSystem.Void,file){HasThis=false};write.Parameters.Add(new ParameterDefinition(module.TypeSystem.String));write.Parameters.Add(new ParameterDefinition(module.TypeSystem.String));
 var exists=module.GetMemberReferences().OfType<MethodReference>().First(x=>x.Name=="Exists"&&x.DeclaringType.FullName=="System.IO.File");var il=method.Body.GetILProcessor();var original=method.Body.Instructions[0];var path=Instruction.Create(OpCodes.Ldstr,"/tmp/vetro-graphite-redirect/request");var caught=Instruction.Create(OpCodes.Callvirt,module.GetMemberReferences().OfType<MethodReference>().First(x=>x.Name=="ToString"&&x.DeclaringType.FullName=="System.Object"));var logger=module.GetMemberReferences().OfType<MethodReference>().First(x=>x.Name=="Error"&&x.Parameters.Count==4&&x.Parameters[0].ParameterType.FullName=="System.String");var done=Instruction.Create(OpCodes.Ret);
 var prefix=new[]{Instruction.Create(OpCodes.Ldarg_1),Instruction.Create(OpCodes.Brfalse,original),Instruction.Create(OpCodes.Ldstr,"/tmp/vetro-graphite-redirect/ready"),Instruction.Create(OpCodes.Call,exists),Instruction.Create(OpCodes.Brfalse,original),path,Instruction.Create(OpCodes.Ldstr,"show"),Instruction.Create(OpCodes.Call,write),Instruction.Create(OpCodes.Leave,done),caught,Instruction.Create(OpCodes.Ldstr,"GraphiteRedirect"),Instruction.Create(OpCodes.Ldstr,"Vetro"),Instruction.Create(OpCodes.Ldc_I4_1),Instruction.Create(OpCodes.Call,logger),Instruction.Create(OpCodes.Leave,original),done};foreach(var i in prefix)il.InsertBefore(original,i);
 method.Body.ExceptionHandlers.Insert(0,new ExceptionHandler(ExceptionHandlerType.Catch){CatchType=exception,TryStart=path,TryEnd=caught,HandlerStart=caught,HandlerEnd=done});method.Body.MaxStackSize=Math.Max(method.Body.MaxStackSize,4);var old=module.Mvid;module.Mvid=Guid.NewGuid();a.Write(args[1]);
 var b=AssemblyDefinition.ReadAssembly(args[1]);int same=0;foreach(var m in b.MainModule.GetTypes().SelectMany(t=>t.Methods)){if(m.FullName==method.FullName)continue;if(!before.ContainsKey(m.FullName)||before[m.FullName]!=Ops(m))throw new Exception("Unexpected changed method: "+m.FullName);same++;}
 Console.WriteLine("Changed exactly one method: "+method.FullName);Console.WriteLine("Verified "+same+" other method bodies unchanged.");Console.WriteLine("Visible requests notify our Home before mapping Samsung's window. Hidden requests retain original code; failed notification falls back to original code.");Console.WriteLine("MVID "+old+" -> "+module.Mvid);return 0;
 }
}
